  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -------------------------------------------------------------\n// ENUMS\n// -------------------------------------------------------------\nenum UserRole {\n  ADMIN\n  DRIVER\n  PLANT_OPERATOR\n}\n\nenum VehicleType {\n  FOUR_WHEELER\n  SIX_WHEELER\n}\n\nenum ShiftStatus {\n  ASSIGNED\n  IN_PROGRESS\n  COMPLETED\n}\n\nenum BagStatus {\n  COLLECTED\n  IN_TRANSIT\n  PLANT_RECEIVED\n  DISPOSED\n}\n\n// -------------------------------------------------------------\n// 0. AUTH & USER MODEL (Role-Based Access Control)\n// -------------------------------------------------------------\nmodel User {\n  id        String   @id @default(uuid())\n  username  String   @unique\n  password  String\n  fullName  String   @map(\"full_name\")\n  role      UserRole @default(DRIVER)\n  driverId  String?  @unique @map(\"driver_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  driver Driver? @relation(fields: [driverId], references: [id])\n\n  @@map(\"users\")\n}\n\n// -------------------------------------------------------------\n// 1. VEHICLE MODEL (Screen 1: Vehicle Registration)\n// -------------------------------------------------------------\nmodel Vehicle {\n  id            String      @id @default(uuid())\n  vehicleNo     String      @unique @map(\"vehicle_no\")\n  vehicleType   VehicleType @map(\"vehicle_type\")\n  qrCodePayload String      @unique @map(\"qr_code_payload\")\n  status        String      @default(\"ACTIVE\")\n  createdAt     DateTime    @default(now()) @map(\"created_at\")\n  updatedAt     DateTime    @updatedAt @map(\"updated_at\")\n\n  dailyMappings DailyDriverMapping[]\n  collectedBags CollectedBag[]\n\n  @@map(\"vehicles\")\n}\n\n// -------------------------------------------------------------\n// 2. HOSPITAL MODEL (For Route stops & Bag collection)\n// -------------------------------------------------------------\nmodel Hospital {\n  id            String   @id @default(uuid())\n  hospitalCode  String   @unique @map(\"hospital_code\")\n  hospitalName  String   @map(\"hospital_name\")\n  qrCodePayload String   @unique @map(\"qr_code_payload\")\n  address       String?\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  routeHospitals RouteHospital[]\n  collectedBags  CollectedBag[]\n\n  @@map(\"hospitals\")\n}\n\n// -------------------------------------------------------------\n// 3. ROUTE & ROUTE STOPS (Screen 2: Vehicle Route Map)\n// -------------------------------------------------------------\nmodel Route {\n  id        String   @id @default(uuid())\n  routeName String   @unique @map(\"route_name\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  routeHospitals RouteHospital[]\n  dailyMappings  DailyDriverMapping[]\n  collectedBags  CollectedBag[]\n\n  @@map(\"routes\")\n}\n\nmodel RouteHospital {\n  id           String   @id @default(uuid())\n  routeId      String   @map(\"route_id\")\n  hospitalId   String   @map(\"hospital_id\")\n  stopSequence Int      @map(\"stop_sequence\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  route    Route    @relation(fields: [routeId], references: [id], onDelete: Cascade)\n  hospital Hospital @relation(fields: [hospitalId], references: [id], onDelete: Cascade)\n\n  @@unique([routeId, hospitalId])\n  @@map(\"route_hospitals\")\n}\n\n// -------------------------------------------------------------\n// 4. DRIVER MODEL (Screen 3: Driver Registration)\n// -------------------------------------------------------------\nmodel Driver {\n  id         String   @id @default(uuid())\n  driverCode String   @unique @map(\"driver_code\")\n  driverName String   @map(\"driver_name\")\n  mobileNo   String   @unique @map(\"mobile_no\")\n  photoUrl   String?  @map(\"photo_url\")\n  isActive   Boolean  @default(true) @map(\"is_active\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  user          User?\n  dailyMappings DailyDriverMapping[]\n  collectedBags CollectedBag[]\n\n  @@map(\"drivers\")\n}\n\n// -------------------------------------------------------------\n// 5. DAILY DRIVER + VEHICLE + ROUTE MAPPING (Screen 4: Assignment)\n// -------------------------------------------------------------\nmodel DailyDriverMapping {\n  id        String      @id @default(uuid())\n  driverId  String      @map(\"driver_id\")\n  vehicleId String      @map(\"vehicle_id\")\n  routeId   String      @map(\"route_id\")\n  shiftDate DateTime    @default(now()) @map(\"shift_date\")\n  status    ShiftStatus @default(IN_PROGRESS)\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n\n  driver        Driver         @relation(fields: [driverId], references: [id])\n  vehicle       Vehicle        @relation(fields: [vehicleId], references: [id])\n  route         Route          @relation(fields: [routeId], references: [id])\n  collectedBags CollectedBag[]\n\n  @@map(\"daily_driver_mappings\")\n}\n\n// -------------------------------------------------------------\n// 6. COLLECTED BAGS (Screen 5 & 6: Collection, Plant Receival, Disposal)\n// -------------------------------------------------------------\nmodel CollectedBag {\n  id              String  @id @default(uuid())\n  bagQrCode       String  @map(\"bag_qr_code\")\n  hospitalId      String  @map(\"hospital_id\")\n  driverMappingId String? @map(\"driver_mapping_id\")\n  driverId        String  @map(\"driver_id\")\n  vehicleId       String  @map(\"vehicle_id\")\n  routeId         String  @map(\"route_id\")\n\n  status          BagStatus @default(COLLECTED)\n  collectedAt     DateTime  @default(now()) @map(\"collected_at\")\n  plantReceivedAt DateTime? @map(\"plant_received_at\")\n  disposedAt      DateTime? @map(\"disposed_at\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  hospital      Hospital            @relation(fields: [hospitalId], references: [id])\n  driverMapping DailyDriverMapping? @relation(fields: [driverMappingId], references: [id])\n  driver        Driver              @relation(fields: [driverId], references: [id])\n  vehicle       Vehicle             @relation(fields: [vehicleId], references: [id])\n  route         Route               @relation(fields: [routeId], references: [id])\n\n  @@index([vehicleId, status])\n  @@index([status])\n  @@map(\"collected_bags\")\n}\n",
